<?php
require __DIR__.'/../app/bootstrap.php'; require_login();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$p=(int)($_POST['patient_id']??0);$d=(int)($_POST['doctor_id']??0);$note=trim((string)($_POST['note_text']??''));if(!$p||!$d||$note==='')flash('Patient, doctor, and medical description are required.','error');else{$s=$pdo->prepare('INSERT INTO medical_notes(patient_id,doctor_id,note_text) VALUES(?,?,?)');$s->execute([$p,$d,$note]);flash('Medical description saved.');}header('Location: medical-notes.php');exit;}
page_start('Medical Notes');show_flash();$patients=$pdo->query('SELECT id,full_name FROM patients ORDER BY full_name')->fetchAll();$doctors=$pdo->query('SELECT id,full_name FROM doctors ORDER BY full_name')->fetchAll();
echo '<section class="panel"><h2>Add medical description</h2>';
if(!$patients||!$doctors)echo '<p>Add at least one patient and one doctor first.</p>';else{echo '<form method="post" class="form-grid"><input type="hidden" name="csrf" value="'.e(csrf_token()).'"><label>Patient<select name="patient_id">';foreach($patients as $p)echo '<option value="'.(int)$p['id'].'">'.e($p['full_name']).'</option>';echo '</select></label><label>Doctor<select name="doctor_id">';foreach($doctors as $d)echo '<option value="'.(int)$d['id'].'">'.e($d['full_name']).'</option>';echo '</select></label><label class="wide">Visit description<textarea name="note_text" rows="4" required maxlength="5000"></textarea></label><button>Save description</button></form>';}echo '</section>';
$rows=$pdo->query('SELECT n.created_at,n.note_text,p.full_name patient,d.full_name doctor FROM medical_notes n JOIN patients p ON p.id=n.patient_id JOIN doctors d ON d.id=n.doctor_id ORDER BY n.id DESC')->fetchAll();
echo '<section class="panel"><h2>Saved descriptions</h2><div class="table-wrap"><table><tr><th>Date</th><th>Patient</th><th>Doctor</th><th>Description</th></tr>';foreach($rows as $r)echo '<tr><td>'.e($r['created_at']).'</td><td>'.e($r['patient']).'</td><td>'.e($r['doctor']).'</td><td>'.nl2br(e($r['note_text'])).'</td></tr>';echo '</table></div></section>';page_end();
